import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { Router, RouterModule } from '@angular/router';
import { AuthService, LoginRequest } from '../../../core/services/auth.service';
import { I18nService } from '../../../core/i18n/i18n.service';
import { TranslationPipe } from '../../../core/i18n/translation.pipe';
import { LangSwitchComponent } from '../../../core/i18n/lang-switch.component';

@Component({
  selector: 'app-login',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule, RouterModule, TranslationPipe, LangSwitchComponent],
  templateUrl: './login.component.html',
  styleUrls: ['./login.component.scss']
})
export class LoginComponent {
  form: FormGroup;
  isLoading = false;
  hasError = false;
  errorMessage = '';

  constructor(
    private fb: FormBuilder,
    private authService: AuthService,
    private router: Router,
    private i18nService: I18nService
  ) {
    this.form = this.fb.group({
      email: ['', [Validators.required, Validators.email]],
      password: ['', [Validators.required, Validators.minLength(6)]]
    });
  }

  get email() {
    return this.form.get('email');
  }

  get password() {
    return this.form.get('password');
  }

  login(): void {
    if (this.form.invalid) {
      return;
    }

    this.isLoading = true;
    this.hasError = false;

    const credentials: LoginRequest = {
      email: this.form.value.email,
      senha: this.form.value.password as string
    };

    this.authService.login(credentials).subscribe({
      next: () => {
        this.isLoading = false;
        const userData = this.authService.getUserData();
        const redirectTo = userData?.role === 1 ? '/admin' : '/dashboard';
        this.router.navigate([redirectTo]);
      },
      error: (error: any) => {
        this.isLoading = false;
        this.hasError = true;
        this.errorMessage = error?.error?.message || this.i18nService.translate('login.invalidCredentials');
      }
    });
  }

  goToRegister(): void {
    this.router.navigate(['/register']);
  }
}
<div class="login-container">
  <div class="login-card">
    <app-lang-switch></app-lang-switch>
    <h1>{{ 'login.title' | t }}</h1>
    <p class="subtitle">{{ 'login.subtitle' | t }}</p>

    <form [formGroup]="form" (ngSubmit)="login()" class="login-form">
      <div class="form-group">
        <label for="email">{{ 'login.emailLabel' | t }}</label>
        <input
          id="email"
          type="email"
          formControlName="email"
          class="form-input"
          [placeholder]="'login.emailPlaceholder' | t"
          [class.error]="email?.invalid && email?.touched"
        />
        <span class="error-message" *ngIf="email?.invalid && email?.touched">
          <span *ngIf="email?.errors?.['required']">{{ 'login.emailRequired' | t }}</span>
          <span *ngIf="email?.errors?.['email']">{{ 'login.emailInvalid' | t }}</span>
        </span>
      </div>

      <div class="form-group">
        <label for="password">{{ 'login.passwordLabel' | t }}</label>
        <input
          id="password"
          type="password"
          formControlName="password"
          class="form-input"
          [placeholder]="'login.passwordPlaceholder' | t"
          [class.error]="password?.invalid && password?.touched"
        />
        <span class="error-message" *ngIf="password?.invalid && password?.touched">
          <span *ngIf="password?.errors?.['required']">{{ 'login.passwordRequired' | t }}</span>
          <span *ngIf="password?.errors?.['minlength']">{{ 'login.passwordMinLength' | t }}</span>
        </span>
      </div>

      <div class="alert alert-error" *ngIf="hasError">
        {{ errorMessage }}
      </div>

      <button
        type="submit"
        class="btn btn-primary"
        [disabled]="form.invalid || isLoading"
      >
        <span *ngIf="!isLoading">{{ 'login.submit' | t }}</span>
        <span *ngIf="isLoading">{{ 'login.submitting' | t }}</span>
      </button>
      <a routerLink="/forgot-password" style="text-align:center; font-size:13px;">Esqueceu a senha?</a>
    </form>

    <div class="form-footer">
      <p>{{ 'login.noAccount' | t }} <a href="javascript:void(0)" (click)="goToRegister()">{{ 'login.createNew' | t }}</a></p>
    </div>
  </div>
</div>
